  function work(id){return typeof id==='string'&&Object.hasOwn(works,id)?works[id]:null;}
  function forArtifact(badgeId,ownerId){
    const mapping={night:'night-bus',ghost:'night-bus-loop',velvet:'night-bus-type',dead:'night-bus-route',unknown:'night-bus-copy',angel:'night-bus'};
    const item=work(mapping[badgeId]);return item?{id:item.id,title:item.title,type:item.type,author:item.author,note:item.note,ownerId:typeof ownerId==='string'?ownerId:''}:null;
  }
